#include "bits/extc++.h"

using namespace std;

template <typename T, typename... U>
void dbgh(const T& t, const U&... u) {
    cerr << t;
    ((cerr << " | " << u), ...);
    cerr << endl;
}

#ifdef DEBUG
#define dbg(...)                                           \
    cerr << "L" << __LINE__ << " [" << #__VA_ARGS__ << "]" \
         << ": ";                                          \
    dbgh(__VA_ARGS__)
#else
#define cerr   \
    if (false) \
    cerr
#define dbg(...)
#endif

using P = pair<int, int>;

#define endl "\n"
#define long int64_t
#define sz(x) int(std::size(x))

bool on(int mask, int bit) {
    return (mask >> bit) & 1;
}

P& operator+=(P& a, const P& b) {
    a.first += b.first;
    a.second += b.second;
    return a;
}

P& operator-=(P& a, const P& b) {
    a.first -= b.first;
    a.second -= b.second;
    return a;
}

P operator+(P a, const P& b) {
    return a += b;
}
P operator-(P a, const P& b) {
    return a -= b;
}

constexpr P dirs[4] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

template <typename T>
T& get(vector<vector<T>>& arr, const P& p) {
    return arr[p.first][p.second];
}

template <typename T>
const T& get(const vector<vector<T>>& arr, const P& p) {
    return arr[p.first][p.second];
}

template <typename T>
void write_i(T& ptr, int x, int bits) {
    assert(bits >= 32 || x < (1 << bits));
    for (int i = 0; i < bits; i++) {
        *(ptr++) = on(x, i);
    }
}

template <typename T>
int read_i(T& ptr, int bits) {
    int ans = 0;
    for (int i = 0; i < bits; i++) {
        ans |= *(ptr++) << i;
    }
    return ans;
}

vector<char> read_base64(const string& s) {
    vector<char> out;
    auto it = back_inserter(out);
    for (auto& a : s) {
        write_i(it, a - '0', 6);
    }
    return out;
}

string write_base64(vector<char> bits) {
    while (sz(bits) % 6) {
        bits.push_back(0);
    }
    auto it = bits.begin();
    string ans;
    for (int i = 0; i < sz(bits); i += 6) {
        ans += char('0' + read_i(it, 6));
    }
    return ans;
}

template <typename T>
void write_p(T& it, const P& p) {
    write_i(it, p.first, 32);
    write_i(it, p.second, 32);
}

template <typename T>
P read_p(T& it) {
    int x = read_i(it, 32), y = read_i(it, 32);
    return {x, y};
}

namespace format1 {

template <typename T>
void write(T& it, const vector<P>& arr) {
    int n = sz(arr);
    write_i(it, n, 32);
    write_p(it, arr[0]);
    for (int i = 1; i < n; i++) {
        P dir = arr[i] - arr[i - 1];
        write_i(it, int(find(begin(dirs), end(dirs), dir) - dirs), 2);
    }
}

template <typename T>
vector<P> read(T& it) {
    int n = read_i(it, 32);
    vector<P> ans;
    ans.push_back(read_p(it));
    for (int i = 1; i < n; i++) {
        ans.push_back(ans.back() + dirs[read_i(it, 2)]);
    }
    return ans;
}

}  // namespace format1

// we could actually barely squeeze everything into 64kb with format 1,
// but then I'd need to delete code and that's no fun
namespace format2 {

template <typename T>
void write(T& it, const vector<P>& arr) {
    write_p(it, arr[0]);

    vector<pair<int, int>> runs;
    for (int i = 1; i < sz(arr); i++) {
        P dir = arr[i] - arr[i - 1];
        int idir = int(find(begin(dirs), end(dirs), dir) - dirs);

        if (!sz(runs) || runs.back().first != idir ||
            runs.back().second == 255) {
            runs.emplace_back(idir, 1);
        } else {
            runs.back().second++;
        }
    }

    write_i(it, sz(runs), 32);
    for (auto& [x, cnt] : runs) {
        write_i(it, x, 2);
        write_i(it, cnt, 8);
    }
}

template <typename T>
vector<P> read(T& it) {
    vector<P> ans;
    ans.push_back(read_p(it));

    int m = read_i(it, 32);
    for (int i = 0; i < m; i++) {
        int idir = read_i(it, 2), cnt = read_i(it, 8);
        for (int j = 0; j < cnt; j++) {
            ans.push_back(ans.back() + dirs[idir]);
        }
    }
    return ans;
}

}  // namespace format2

template <typename Cb>
string write_all(const vector<vector<P>>& arr, const Cb& cb) {
    vector<char> ans;
    auto it = back_inserter(ans);
    int n = sz(arr);
    write_i(it, n, 32);
    for (int i = 0; i < n; i++) {
        cb(it, arr[i]);
    }
    return write_base64(ans);
}

template <typename Cb>
vector<vector<P>> read_all(const string& data, const Cb& cb) {
    vector<char> bits = read_base64(data);
    auto it = bits.begin();
    int n = read_i(it, 32);
    vector<vector<P>> ans;
    for (int i = 0; i < n; i++) {
        ans.push_back(cb(it));
    }
    return ans;
}

vector<vector<P>> read_out(istream& in) {
    int ckv;
    in >> ckv;
    vector<vector<P>> ans(ckv);
    for (auto& a : ans) {
        int csz;
        in >> csz;
        a.resize(csz);
        for (auto& [x, y] : a) {
            in >> x >> y;
            x--;
            y--;
        }
    }
    return ans;
}

