void print(ostream& out, const vector<vector<P>>& ans) {
    out << sz(ans) << endl;
    for (auto& a : ans) {
        out << sz(a);
        for (auto& b : a) {
            out << " " << b.first + 1 << " " << b.second + 1;
        }
        out << endl;
    }
}

void solve() {
    int tc;
    cin >> tc;
    vector<vector<P>> cans;
    if (tc != 8) {
        cans = read_all(D_ANS[tc], format1::read<vector<char>::iterator>);
    } else {
        cans = read_all(D_ANS[tc], format2::read<vector<char>::iterator>);
    }
    print(cout, cans);
}

int main() {
    cin.tie(nullptr);
    cin.exceptions(ios::failbit);
    ios_base::sync_with_stdio(false);
    solve();
}